"""Hidden behavioral tests for cmark: render_man. Generated by pbkit from the gold binary."""


def test_kitchen_sink_man(run):
    r = run(args=['-t', 'man'], stdin=b'# Heading *one*\n\nSetext heading\n--------------\n\nA paragraph with *emph*, **strong**, ***both***, `code`, a [link](http://example.com "Title"),\nan ![image](img.png "Img"), <http://auto.link>, <me@example.com>, a hard\\\nbreak and a soft\nbreak. Entities: &copy; &#x27; &#39; &nbsp;. Backslash \\* escapes.\n\n> A block quote\n> with *two* lines\n>\n> > nested quote\n\n1. first\n2. second\n   - nested bullet\n   - another\n\n     with a paragraph\n3. third\n\n- [ ] not a task list\n* different bullet\n\n```python\ndef f(x):\n    return x * 2\n```\n\n    indented code block\n\n<div class="raw">\n*not emph*\n</div>\n\nInline <span>html</span> and <!-- comment -->.\n\n***\n\n[ref link][ref] and [collapsed][] and [shortcut].\n\n[ref]: /url "ref title"\n[collapsed]: </with spaces>\n[shortcut]: http://x.y \'single\'\n')
    assert r.stdout == b'.SH\nHeading \\f[I]one\\f[]\n.SS\nSetext heading\n.PP\nA paragraph with \\f[I]emph\\f[], \\f[B]strong\\f[], \\f[I]\\f[B]both\\f[]\\f[], \\f[C]code\\f[], a link (http://example.com),\nan [IMAGE: image], http://auto.link (http://auto.link), me@example.com (mailto:me@example.com), a hard.PD 0\n.P\n.PD\nbreak and a soft\nbreak. Entities: \xc2\xa9 \' \' \xc2\xa0. Backslash * escapes.\n.RS\n.PP\nA block quote\nwith \\f[I]two\\f[] lines\n.RS\n.PP\nnested quote\n.RE\n.RE\n.IP "1." 4\nfirst\n.IP "2." 4\nsecond\n.RS\n.IP \\[bu] 2\nnested bullet\n.IP \\[bu] 2\nanother\n.RS\n.PP\nwith a paragraph\n.RE\n.RE\n.IP "3." 4\nthird\n.IP \\[bu] 2\n[ ] not a task list\n.IP \\[bu] 2\ndifferent bullet\n.IP\n.nf\n\\f[C]\ndef f(x):\n    return x * 2\n\\f[]\n.fi\n.IP\n.nf\n\\f[C]\nindented code block\n\\f[]\n.fi\n.PP\nInline html and .\n.PP\n  *  *  *  *  *\n.PP\nref link (/url) and collapsed (/with spaces) and shortcut (http://x.y).\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_lists_man(run):
    r = run(args=['-t', 'man'], stdin=b'- a\n- b\n\n- c\n\n1) x\n2) y\n\n10. ten\n11. eleven\n\n* loose\n\n  para\n* tight\n')
    assert r.stdout == b'.IP \\[bu] 2\na\n.IP \\[bu] 2\nb\n.IP \\[bu] 2\nc\n.IP "1." 4\nx\n.IP "2." 4\ny\n.IP "10." 4\nten\n.IP "11." 4\neleven\n.IP \\[bu] 2\nloose\n.RS\n.PP\npara\n.RE\n.IP \\[bu] 2\ntight\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_quotes_and_dashes_man(run):
    r = run(args=['-t', 'man'], stdin=b'"Hello," said the spider. \'Shelob\' is my name -- or --- maybe... it\'s 1990\'s.\n')
    assert r.stdout == b'.PP\n"Hello," said the spider. \'Shelob\' is my name \\-\\- or \\-\\-\\- maybe... it\'s 1990\'s.\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_special_chars_man(run):
    r = run(args=['-t', 'man'], stdin=b'Special: \\ { } $ & # ^ _ % ~ < > " \' | and . at line start\n\n.SH not a macro\n\'quote\n')
    assert r.stdout == b'.PP\nSpecial: \\e { } $ & # ^ _ % ~ < > " \' | and . at line start\n.PP\n\\&.SH not a macro\n\\&\'quote\n'
    assert r.stderr == b''
    assert r.returncode == 0


